#include <iostream>
#include <memory>
class Base {
public:
  virtual void foo() { std::cout << "Base::foo\n"; }
};
class Derived : public Base {
public:
  void foo() override { std::cout << "Derived::foo\n"; }
};
int main() {
  Base* basePtr = new Derived();
  basePtr->foo(); // Calls Derived::foo due to polymorphism and vtable
  delete basePtr;
  return 0;
}
